import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Lista de Autoverificación de Contradicciones de Configuración","description":"","frontmatter":{},"headers":[],"relativePath":"es/97-设定矛盾自查表.md","filePath":"es/97-设定矛盾自查表.md"}'),n={name:"es/97-设定矛盾自查表.md"};function d(r,e,s,c,l,u){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="lista-de-autoverificacion-de-contradicciones-de-configuracion" tabindex="-1">Lista de Autoverificación de Contradicciones de Configuración <a class="header-anchor" href="#lista-de-autoverificacion-de-contradicciones-de-configuracion" aria-label="Permalink to &quot;Lista de Autoverificación de Contradicciones de Configuración&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>97</td></tr><tr><td>Módulo</td><td>Apéndices y Materiales de Referencia</td></tr><tr><td>Palabras clave</td><td>autoverificación de contradicciones, coherencia de la configuración, verificación lógica, control de calidad, mantenimiento de la configuración</td></tr></tbody></table><h2 id="i-notas" tabindex="-1">I. Notas <a class="header-anchor" href="#i-notas" aria-label="Permalink to &quot;I. Notas&quot;">​</a></h2><p>La Lista de Autoverificación de Contradicciones de Configuración es la herramienta de control de calidad del sistema de configuración de la Civilización Simbiótica del Ancla, utilizada para identificar sistemáticamente posibles contradicciones de configuración e incoherencias lógicas al crear nuevas configuraciones, revisar configuraciones antiguas y actualizar documentos. Esta lista de autoverificación se elabora sobre la base de las 14 configuraciones centrales y la lista de comprobación de coherencia establecidas en SPEC.md, y abarca todos los módulos: cosmovisión, sistema de cultivo, sistema social, sistema jurídico, formas de vida, sistema tecnológico, eras históricas, interacción transplanar, etc. Todo contenido nuevo o revisado debe superar todos los puntos de comprobación de esta lista antes de incorporarse oficialmente al sistema de configuración.</p><h2 id="ii-comprobaciones-de-coherencia-de-la-configuracion-central" tabindex="-1">II. Comprobaciones de coherencia de la configuración central <a class="header-anchor" href="#ii-comprobaciones-de-coherencia-de-la-configuracion-central" aria-label="Permalink to &quot;II. Comprobaciones de coherencia de la configuración central&quot;">​</a></h2><h3 id="_2-1-nombres-del-universo-y-conceptos-fundamentales" tabindex="-1">2.1 Nombres del universo y conceptos fundamentales <a class="header-anchor" href="#_2-1-nombres-del-universo-y-conceptos-fundamentales" aria-label="Permalink to &quot;2.1 Nombres del universo y conceptos fundamentales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>C01</td><td>Unificación del nombre del universo</td><td>Todo el texto utiliza uniformemente «Universo Original Wanling Hengmao» o la abreviatura «Universo Hengyuan»; no puede usarse ningún otro nombre</td><td>Mezcla de nombres no estándar: «universo», «diez mil mundos», «todos los cielos», etc.</td></tr><tr><td>C02</td><td>Coherencia de la definición del Ancla</td><td>El Ancla siempre se define como «un nodo estable en la red de leyes»; sus atributos esenciales no pueden modificarse</td><td>Describir el Ancla como un objeto, un ser o un cuerpo de energía</td></tr><tr><td>C03</td><td>Unificación del concepto de simbiosis</td><td>La simbiosis siempre significa «la evolución común de diferentes vidas mediante la cooperación mutuamente beneficiosa»; no se permite desviarse de la postura contra la depredación</td><td>Describir la simbiosis como asimilación, anexión o control</td></tr><tr><td>C04</td><td>Coherencia de la postura central</td><td>Mantener siempre el principio de «La Realidad como Fundamento»; las configuraciones ficticias no pueden describirse como reales</td><td>Confundir la frontera entre ficción y realidad</td></tr></tbody></table><h3 id="_2-2-coherencia-del-sistema-de-cultivo" tabindex="-1">2.2 Coherencia del sistema de cultivo <a class="header-anchor" href="#_2-2-coherencia-del-sistema-de-cultivo" aria-label="Permalink to &quot;2.2 Coherencia del sistema de cultivo&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>C05</td><td>Coherencia del número total de sistemas</td><td>El número total de Sistemas de Cultivo de Origen es siempre trescientos; no puede aumentarse ni disminuirse</td><td>Expresiones vagas: «más de trescientos», «varios cientos»</td></tr><tr><td>C06</td><td>Coherencia de la clasificación de los sistemas</td><td>Siempre divididos en seis grandes categorías (deducción de origen, ciclo de vida, principios legales espaciales, ascensión de la conciencia, red simbiótica, ingeniería aplicada), con cincuenta sistemas en cada categoría</td><td>Otras clasificaciones o números de categorías incoherentes</td></tr><tr><td>C07</td><td>Coherencia de las Tres Bases de Origen</td><td>Los tres primeros sistemas son siempre Iteración Deductiva (001), Ciclo de Vida (002) y Despacho de Principios Legales Espaciales (003)</td><td>Cambiar los números o nombres de los tres primeros sistemas</td></tr><tr><td>C08</td><td>Coherencia de la configuración del Fruto Multiplicador</td><td>El Fruto Multiplicador siempre es un «buff de apertura», que proporciona una amplificación deductiva centuplicada, y ha sido tecnológicamente aplicado</td><td>Describir el Fruto Multiplicador como un fruto natural o como no tecnificado</td></tr><tr><td>C09</td><td>Coherencia de los reinos de cultivo</td><td>Las divisiones de reinos de cada sistema permanecen conformes al documento 14 «División Unificada de los Reinos de Cultivo»</td><td>Inventar nombres de reinos que contradicen la división unificada</td></tr><tr><td>C10</td><td>Coherencia de la postura contra la depredación</td><td>El cultivo depredador no puede describirse como un sistema positivo o aceptable</td><td>Defender o embellecer el cultivo depredador</td></tr></tbody></table><h3 id="_2-3-coherencia-social-y-juridica" tabindex="-1">2.3 Coherencia social y jurídica <a class="header-anchor" href="#_2-3-coherencia-social-y-juridica" aria-label="Permalink to &quot;2.3 Coherencia social y jurídica&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>C11</td><td>Coherencia de las tipologías de civilización</td><td>Siempre las Cinco Tipologías (Intensiva de Asia Oriental, Bienestar Nórdico, Pluralista de América del Norte, Social Continental Europeo, Desarrollo con Puesta al Día)</td><td>Aparece una sexta tipología o se cambian los nombres de las tipologías</td></tr><tr><td>C12</td><td>Coherencia del sistema jurídico</td><td>Siempre Constitución + Ley del Trabajo + Ley de Protección del Consumidor + cinco leyes complementarias (educación, sanidad, vivienda, medio ambiente, antimonopolio)</td><td>Omitir una ley o añadir una ley no establecida</td></tr><tr><td>C13</td><td>Coherencia de la estructura de gobernanza</td><td>Siempre Asamblea Legislativa del Ancla (legislativo) + Comité Ejecutivo Simbiótico (ejecutivo) + Tribunal Simbiótico (judicial) + Comité de Supervisión del Ancla (supervisión)</td><td>Cambiar los nombres de las instituciones o la distribución de poderes</td></tr><tr><td>C14</td><td>Coherencia del Mecanismo de Contrato Vinculado a la Producción</td><td>Siempre centrado en «más trabajo, más ganancia»; la distribución de recursos se basa en la contribución</td><td>Describir el Contrato Vinculado a la Producción como igualitarismo o distribución según la necesidad</td></tr><tr><td>C15</td><td>Coherencia de la Estrategia de Activación del 20 %</td><td>Siempre activar al 20 % de los seres como Potencias Supremas del Plano en la fase inicial</td><td>Cambiar el porcentaje o el objetivo de activación</td></tr></tbody></table><h2 id="iii-comprobaciones-de-coherencia-logica-entre-modulos" tabindex="-1">III. Comprobaciones de coherencia lógica entre módulos <a class="header-anchor" href="#iii-comprobaciones-de-coherencia-logica-entre-modulos" aria-label="Permalink to &quot;III. Comprobaciones de coherencia lógica entre módulos&quot;">​</a></h2><h3 id="_3-1-coherencia-de-la-linea-temporal" tabindex="-1">3.1 Coherencia de la línea temporal <a class="header-anchor" href="#_3-1-coherencia-de-la-linea-temporal" aria-label="Permalink to &quot;3.1 Coherencia de la línea temporal&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>L01</td><td>Coherencia de las fechas de los acontecimientos históricos</td><td>Las fechas de todos los acontecimientos históricos permanecen conformes al documento 93 «Tabla Maestra de la División de Eras» y a los documentos 70-79</td><td>El mismo acontecimiento tiene fechas incoherentes en diferentes documentos</td></tr><tr><td>L02</td><td>Coherencia de la división de eras</td><td>Los nombres de las eras y las fechas de inicio y fin permanecen conformes al documento 70 «Tabla Maestra de la División de Eras»</td><td>Aparecen eras no establecidas o se modifican las fronteras de las eras</td></tr><tr><td>L03</td><td>Coherencia de los períodos de las figuras</td><td>Los períodos de actividad de las figuras clave permanecen conformes al documento 95 «Figuras Clave y Organizaciones»</td><td>Una figura aparece en una era en la que no existía</td></tr><tr><td>L04</td><td>Coherencia de las fechas de las tecnologías</td><td>Las fechas de invención y maduración de cada tecnología permanecen conformes a la cronología</td><td>Una tecnología se utiliza en una era anterior a su invención</td></tr></tbody></table><h3 id="_3-2-coherencia-del-sistema-tecnologico" tabindex="-1">3.2 Coherencia del sistema tecnológico <a class="header-anchor" href="#_3-2-coherencia-del-sistema-tecnologico" aria-label="Permalink to &quot;3.2 Coherencia del sistema tecnológico&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>T01</td><td>Coherencia de la tecnología del Espejo de Réplica</td><td>El Espejo de Réplica siempre es «un dispositivo de réplica 1:1 que no toca el original», con interferencia cero en el proceso de réplica</td><td>Describir el Espejo de Réplica como capaz de alterar el original o de requerir contacto con el original</td></tr><tr><td>T02</td><td>Coherencia del espacio aislado</td><td>El espacio aislado siempre es «un espacio independiente totalmente separado del exterior por barreras de leyes»</td><td>Describir el espacio aislado como una habitación ordinaria o un espacio virtual</td></tr><tr><td>T03</td><td>Coherencia de los requisitos de cultivo de principios legales espaciales</td><td>Los requisitos de cultivo de cada tecnología espacial permanecen conformes al documento 13 «Explicación Detallada del Sistema de Despacho de Principios Legales Espaciales»</td><td>Cultivadores de bajo nivel utilizan tecnologías que exigen altos niveles</td></tr><tr><td>T04</td><td>Coherencia de las unidades de energía</td><td>La medición de la energía utiliza uniformemente la «unidad estándar de energía»; no pueden usarse otras unidades</td><td>Mezcla de unidades no estándar: «piedras espirituales», «monedas de cristal», etc.</td></tr></tbody></table><h3 id="_3-3-coherencia-de-las-reglas-transplanares-y-temporales" tabindex="-1">3.3 Coherencia de las reglas transplanares y temporales <a class="header-anchor" href="#_3-3-coherencia-de-las-reglas-transplanares-y-temporales" aria-label="Permalink to &quot;3.3 Coherencia de las reglas transplanares y temporales&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>K01</td><td>Coherencia de «observar primero, luego intervenir dentro de límites»</td><td>Todas las operaciones de regresión temporal y transplanares deben seguir este principio; la fase de observación no puede omitirse</td><td>Describir operaciones que intervienen directamente sin observación</td></tr><tr><td>K02</td><td>Coherencia del «retorno de solo conocimiento»</td><td>El producto arqueológico se limita a conocimiento e información abstractos; no pueden retornarse materia, energía ni formas de vida</td><td>Describir el acto de traer artefactos o muestras al plano de origen</td></tr><tr><td>K03</td><td>Coherencia del sistema de permisos de tránsito</td><td>Todo tránsito entre planos debe obtener un permiso del nivel correspondiente; el tránsito sin permiso no está permitido</td><td>Describir tránsitos no autorizados</td></tr><tr><td>K04</td><td>Coherencia de la clasificación de las paradojas temporales</td><td>Las paradojas siempre se dividen en cuatro categorías — parricidio, informacional, ontológica y de evento; no se permiten adiciones ni cambios</td><td>Aparecen tipos de paradojas no establecidos</td></tr><tr><td>K05</td><td>Coherencia de la clasificación de los planos</td><td>Los planos siempre se dividen en cinco grandes categorías (material-sustancial, manifestación de energía, dominado por la conciencia, leyes fragmentadas, vecino del origen)</td><td>Aparecen otras clasificaciones</td></tr></tbody></table><h3 id="_3-4-coherencia-de-la-vida-y-las-razas" tabindex="-1">3.4 Coherencia de la vida y las razas <a class="header-anchor" href="#_3-4-coherencia-de-la-vida-y-las-razas" aria-label="Permalink to &quot;3.4 Coherencia de la vida y las razas&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>S01</td><td>Coherencia de la clasificación de las razas</td><td>Las razas siempre se dividen en ocho grandes categorías (forma humanoide, animal, vegetal, elemental, energética, de conciencia, mecánica, híbrida)</td><td>Aparecen otras clasificaciones</td></tr><tr><td>S02</td><td>Coherencia del tratamiento de la Vida Anómala</td><td>La Vida Anómala siempre se trata según los tres tipos de procedimientos normalizados de tratamiento</td><td>Describir tratamientos arbitrarios fuera de los procedimientos</td></tr><tr><td>S03</td><td>Coherencia del tratamiento de las Entidades Oscuras de Reemplazo</td><td>Las Entidades Oscuras de Reemplazo siempre se tratan según las Directrices Éticas del Alma Dual y las reglas de tratamiento de las cuatro ramas</td><td>Describir el acto de simplemente eliminar un alma</td></tr><tr><td>S04</td><td>Coherencia de la igualdad de las Diez Mil Razas</td><td>Todas las razas inteligentes son iguales ante la ley; las configuraciones de discriminación racial no están permitidas</td><td>Describir una raza como naturalmente inferior o destinada a la esclavitud</td></tr></tbody></table><h2 id="iv-comprobaciones-de-formato-y-normas-documentales" tabindex="-1">IV. Comprobaciones de formato y normas documentales <a class="header-anchor" href="#iv-comprobaciones-de-formato-y-normas-documentales" aria-label="Permalink to &quot;IV. Comprobaciones de formato y normas documentales&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Punto de comprobación</th><th>Contenido de la comprobación</th><th>Criterio de aprobación</th><th>Problemas comunes</th></tr></thead><tbody><tr><td>F01</td><td>Corrección del formato del nombre de archivo</td><td>El formato del nombre de archivo es «XX-Título del documento.md», donde XX es un número de dos dígitos</td><td>Número ausente, título con espacios, extensión de archivo errónea</td></tr><tr><td>F02</td><td>Integridad del bloque de información del documento</td><td>El comienzo contiene una tabla de información con número, módulo y palabras clave centrales (3-5)</td><td>Bloque ausente o campos incompletos</td></tr><tr><td>F03</td><td>Suficiencia de los títulos de nivel dos</td><td>El cuerpo contiene al menos 3 secciones con títulos de nivel dos</td><td>Menos de 3 títulos de nivel dos</td></tr><tr><td>F04</td><td>Uso de elementos estructurados</td><td>Se utilizan listas, tablas y otros elementos estructurados para mejorar la legibilidad</td><td>Párrafos de texto puro sin listas ni tablas</td></tr><tr><td>F05</td><td>Existencia de la conclusión</td><td>Al final existe un párrafo de «Conclusión»</td><td>Conclusión ausente</td></tr><tr><td>F06</td><td>Existencia de los documentos relacionados</td><td>Al final se enumeran 2-3 números y nombres de documentos relacionados</td><td>Documentos relacionados ausentes o inexistentes</td></tr><tr><td>F07</td><td>Suficiencia de la extensión</td><td>El cuerpo no debe ser inferior a 800 caracteres (excluyendo títulos y metainformación)</td><td>Cuerpo inferior a 800 caracteres</td></tr><tr><td>F08</td><td>Unificación de la terminología</td><td>Se utilizan términos estándar como «Universo Hengyuan», «Ancla» y «Simbiosis»</td><td>Terminología no unificada o expresiones no estándar</td></tr><tr><td>F09</td><td>Idoneidad del estilo de escritura</td><td>Estilo serio y sistemático de documento de configuración, sin expresiones coloquiales</td><td>Aparición de expresiones coloquiales o informales</td></tr><tr><td>F10</td><td>Concordancia de los números con la lista</td><td>Los números y títulos de los documentos son conformes a la lista completa de los 100 documentos de SPEC.md</td><td>Números o títulos no conformes con la lista</td></tr></tbody></table><h2 id="v-proceso-de-autoverificacion-y-modo-de-empleo" tabindex="-1">V. Proceso de autoverificación y modo de empleo <a class="header-anchor" href="#v-proceso-de-autoverificacion-y-modo-de-empleo" aria-label="Permalink to &quot;V. Proceso de autoverificación y modo de empleo&quot;">​</a></h2><h3 id="_5-1-proceso-de-autoverificacion-para-la-creacion-de-nuevas-configuraciones" tabindex="-1">5.1 Proceso de autoverificación para la creación de nuevas configuraciones <a class="header-anchor" href="#_5-1-proceso-de-autoverificacion-para-la-creacion-de-nuevas-configuraciones" aria-label="Permalink to &quot;5.1 Proceso de autoverificación para la creación de nuevas configuraciones&quot;">​</a></h3><ol><li><strong>Autoverificación preliminar</strong>: una vez completada la creación, el creador comprueba punto por punto contra esta lista y marca los puntos problemáticos.</li><li><strong>Revisión y perfeccionamiento</strong>: revisar los puntos marcados para asegurar que todos pasen.</li><li><strong>Revisión cruzada</strong>: enviar a otro creador de configuración para una revisión cruzada, centrada en la coherencia entre módulos.</li><li><strong>Aprobación del Comité</strong>: los cambios importantes de configuración deben presentarse al Comité de Mantenimiento de la Configuración para su aprobación.</li><li><strong>Actualización de archivo</strong>: tras superar todas las comprobaciones, incorporar oficialmente al sistema de configuración y actualizar los documentos de índice correspondientes.</li></ol><h3 id="_5-2-proceso-de-autoverificacion-para-revisar-configuraciones-antiguas" tabindex="-1">5.2 Proceso de autoverificación para revisar configuraciones antiguas <a class="header-anchor" href="#_5-2-proceso-de-autoverificacion-para-revisar-configuraciones-antiguas" aria-label="Permalink to &quot;5.2 Proceso de autoverificación para revisar configuraciones antiguas&quot;">​</a></h3><ol><li><strong>Evaluación de impacto</strong>: evaluar los otros documentos y módulos de configuración que el contenido revisado pueda afectar.</li><li><strong>Comprobaciones de los documentos relacionados</strong>: realizar comprobaciones de coherencia en todos los documentos relacionados afectados.</li><li><strong>Revisión sincronizada</strong>: revisar en sincronización el contenido afectado en los documentos relacionados.</li><li><strong>Registro de versión</strong>: registrar el contenido de la revisión y el número de versión en el documento 99 «Versión de Documentos y Notas de Mantenimiento».</li><li><strong>Aviso de anuncio</strong>: las revisiones importantes deben publicar un aviso de cambio a todos los usuarios de la configuración.</li></ol><h3 id="_5-3-autoverificacion-completa-periodica" tabindex="-1">5.3 Autoverificación completa periódica <a class="header-anchor" href="#_5-3-autoverificacion-completa-periodica" aria-label="Permalink to &quot;5.3 Autoverificación completa periódica&quot;">​</a></h3><p>El Comité de Mantenimiento de la Configuración realiza cada trimestre una autoverificación completa de la coherencia de la configuración, comprobando sistemáticamente los 100 documentos para identificar posibles contradicciones de configuración e incoherencias lógicas. Los resultados de la autoverificación conforman el «Informe Trimestral de Coherencia de la Configuración», que se hace público a todos los usuarios de la configuración.</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La Lista de Autoverificación de Contradicciones de Configuración es la «constitución de la calidad» del sistema de configuración de la Civilización Simbiótica del Ancla. Mediante puntos de comprobación sistematizados y en formato de lista, garantiza que el sistema de configuración mantenga siempre la autocoherencia lógica y la unificación terminológica en el proceso de expansión y revisión continuas. Lo que un vasto sistema de configuración teme no es la falta de riqueza de contenido, sino la proliferación de contradicciones internas y la incoherencia entre sus partes. La existencia de esta lista de autoverificación busca precisamente que el sistema de configuración de la Civilización Simbiótica del Ancla, manteniendo su apertura y crecimiento, posea siempre un fundamento sólido de coherencia.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>99-文档版本与维护说明 (Versión de Documentos y Notas de Mantenimiento)</li><li>90-术语词典 (El Diccionario de Terminología)</li><li>00-衡元宙宇宙总览 (Heng Yuan Zhou: Panorama del Cosmos)</li></ul>',33)])])}const h=a(n,[["render",d]]);export{p as __pageData,h as default};
